        .arg(Arg::new("from").short('f').long("from").value_name("COMMIT").help("e.g. 12a8546").conflicts_with("from-latest-tag"))
        .arg(Arg::new("format").short('T').long("format").value_name("STR").help("The output format, defaults to markdown").value_parser(value_parser!(clap::builder::PossibleValuesParser::new(["markdown", "json"]))).default_value("markdown"))
