        .arg(Arg::new("work-tree").short('w').long("work-tree").value_name("PATH").help("Local working tree of the git project (defaults to \"$(pwd)\")"))
        .arg(Arg::new("minor").short('m').long("minor").help("Increment minor version by one (Sets patch to 0)").action(ArgAction::SetTrue))
        .arg(Arg::new("patch").short('p').long("patch").help("Increment patch version by one").action(ArgAction::SetTrue))
